import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·32","description":"易小帖 - 卷一·32","frontmatter":{"title":"卷一·32","description":"易小帖 - 卷一·32"},"headers":[],"relativePath":"zh/classics/yixiaotie/032.md","filePath":"zh/classics/yixiaotie/032.md"}'),o={name:"zh/classics/yixiaotie/032.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·32",tabindex:"-1"},[r("卷一·32 "),e("a",{class:"header-anchor",href:"#卷一·32","aria-label":"Permalink to “卷一·32”"},"​")],-1),e("p",null,"大畜「何天之衢」，何荷通，即在噬嗑「何校」已有之，故鄭康成曰：「艮為手，乾為首。」而肩當首手之間，荷物處也，則分明是負荷之義。故康成又曰：「乾為天，艮為徑路，此天衢也。」則實言大畜三陽不家食而登天衢，於卦義爻義兩俱瞭然。《程傳》解爻詞則曰：「誤加何字。」解《象傳》則又曰：「何以謂之天衢？」作詰問解。至《本義》又曰：「何其通達之甚。」此皆惑於王輔嗣語詞之註而誤之者。宋人極倔強，獨於王註則遵若科律。歐陽修謂：「易無王註，則淪於異端。」反謂大衍非文王之事，《說卦》非聖人之言，其敢於毀孔子而必不敢違輔嗣。何以至此。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
